<?php
$pageTitle='Checkout | Moleqra';require_once __DIR__.'/includes/bootstrap.php';require_once __DIR__.'/includes/commerce.php';require_once __DIR__.'/includes/account_auth.php';$pdo=db();$error='';$user=customer_user();
if(!$pdo||!commerce_schema_ready($pdo)||!commerce_enabled()){http_response_code(503);$error='Online checkout is not currently available.';}
$cart=$pdo&&commerce_schema_ready($pdo)?commerce_cart_details($pdo):['items'=>[],'grand_total'=>0,'subtotal'=>0,'tax'=>0,'shipping'=>0];
if($_SERVER['REQUEST_METHOD']==='POST'&&!$error){if(!csrf_valid($_POST['csrf_token']??null))$error='Your session expired.';else{try{$data=$_POST;$data['ruo_acknowledged']=isset($_POST['ruo_acknowledged']);$data['terms_accepted']=isset($_POST['terms_accepted']);$order=commerce_create_order($pdo,$data,$user['id']??null);header('Location: payment/payfast-start.php?token='.$order['order_token']);exit;}catch(Throwable $e){$error=$e instanceof RuntimeException?$e->getMessage():'Checkout could not be completed.';}}}
require __DIR__.'/includes/header.php';
?>
<section class="page-hero"><div class="container"><div class="eyebrow">Secure checkout</div><h1>Checkout</h1><p>Your payment will be completed on PayFast's hosted payment page.</p></div></section><section class="section"><div class="container"><?php if($error):?><div class="alert error"><?= e($error) ?></div><?php endif;?><?php if($cart['items']):?><div class="checkout-layout"><form method="post" class="card"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><h2>Contact & shipping</h2><div class="form-grid"><div class="field"><label>First name</label><input name="first_name" required maxlength="100" value="<?= e($_POST['first_name']??$user['first_name']??'') ?>"></div><div class="field"><label>Last name</label><input name="last_name" required maxlength="100" value="<?= e($_POST['last_name']??$user['last_name']??'') ?>"></div><div class="field"><label>Email</label><input type="email" name="email" required maxlength="180" value="<?= e($_POST['email']??$user['email']??'') ?>"></div><div class="field"><label>Phone</label><input name="phone" maxlength="60" value="<?= e($_POST['phone']??$user['phone']??'') ?>"></div><div class="field full"><label>Company / research organisation</label><input name="company" maxlength="160" value="<?= e($_POST['company']??$user['company']??'') ?>"></div><div class="field full"><label>Address</label><input name="address_line1" required maxlength="180" value="<?= e($_POST['address_line1']??'') ?>"></div><div class="field full"><label>Address line 2</label><input name="address_line2" maxlength="180" value="<?= e($_POST['address_line2']??'') ?>"></div><div class="field"><label>City</label><input name="city" required maxlength="120" value="<?= e($_POST['city']??'') ?>"></div><div class="field"><label>Province</label><input name="province" required maxlength="120" value="<?= e($_POST['province']??'') ?>"></div><div class="field"><label>Postal code</label><input name="postal_code" required maxlength="30" value="<?= e($_POST['postal_code']??'') ?>"></div><div class="field full"><label>Order note</label><textarea name="customer_note"><?= e($_POST['customer_note']??'') ?></textarea></div></div><div class="checkout-consents"><label><input type="checkbox" name="ruo_acknowledged" required> I confirm this order is for legitimate research/laboratory purposes and acknowledge the products are not for human or veterinary use.</label><label><input type="checkbox" name="terms_accepted" required> I accept Moleqra's <a href="terms.php" target="_blank">terms</a> and <a href="privacy.php" target="_blank">privacy notice</a>.</label></div><button class="btn primary" type="submit">Continue to PayFast</button></form><aside class="card checkout-sidebar"><h2>Order summary</h2><?php foreach($cart['items'] as $item):?><p><span><?= e($item['product']['name']) ?> × <?= e((string)$item['quantity']) ?></span><strong><?= commerce_money($item['totals']['total']) ?></strong></p><?php endforeach;?><hr><p><span>Shipping</span><strong><?= $cart['shipping']?commerce_money($cart['shipping']):'Free' ?></strong></p><p class="checkout-total"><span>Total</span><strong><?= commerce_money($cart['grand_total']) ?></strong></p><small class="muted">Stock is reserved for a limited period when you submit checkout.</small></aside></div><?php elseif(!$error):?><div class="card"><h2>Your cart is empty.</h2><a class="btn" href="catalog.php">Browse catalogue</a></div><?php endif;?></div></section><?php require __DIR__.'/includes/footer.php';?>
